test('retry after an actual failed or empty local read clears old feedback while pending and fences earlier completions',async()=>{
 const {LocalMusicRefresh}=await import('../../podvoice/gatekeeper/static/podview/flow-controller.js'),{initialScene,sceneTransition}=await import('../../podvoice/gatekeeper/static/podview/scene-model.js');for(const outcome of ['error','empty']){const f=retainedResultSurface(),callbacks=[],cancelled=[];let result=outcome;f.host.isConnected=true;f.host.state={...initialScene(),focus:'music'};f.host.render=()=>f.view.render({cards:localDiscoveryCards(f.host.state),busy:!!f.host.state.music.refreshPending,connected:f.host.state.connected});f.host.musicRefresh=new LocalMusicRefresh(f.host,{outcome:()=>result,after(fn){callbacks.push(fn);return callbacks.length;},cancel:id=>cancelled.push(id)});f.host.dispatch=event=>{f.host.state=sceneTransition(f.host.state,event);f.host.musicRefresh.sync();f.host.render();};f.host.render();const rows=[...f.nodes.get('result-list').children],player=f.host.state.music.playback;f.host.musicRefresh.start();callbacks[0]();assert.equal(f.nodes.get('empty').hidden,false);assert.equal(f.nodes.get('empty').dataset.refreshOutcome,outcome);assert.deepEqual(f.nodes.get('result-list').children,rows);f.host.musicRefresh.start();assert.equal(f.nodes.get('empty').hidden,true);assert.equal(f.nodes.get('music-refresh').label.textContent,'Henter forslag');const retry=f.host.state;callbacks[0]();assert.equal(f.host.state,retry);result='ready';callbacks[1]();assert.equal(f.nodes.get('empty').hidden,true);assert.equal(f.nodes.get('music-refresh').label.textContent,'Andre forslag');assert.equal(f.host.state.music.playback,player);assert.deepEqual(f.nodes.get('result-list').children,rows,'refresh retains button slots');assert.equal(rows[0].musicCard.id,localDiscoveryCards(f.host.state)[0].id,'retained slot dispatches the new option');f.view.cleanup();}
});

