test('refresh crossfades only retained art/copy, never the button or Play, and cleanup cancels all layers',async()=>{
 const f=retainedResultSurface(),cards=resultCards();f.view.render({cards});const rows=[...f.nodes.get('result-list').children],calls=[];
 f.host.motion={reduced:false,animate(node,frames,duration){let resolve;const animation={finished:new Promise(done=>resolve=done),cancelled:false,cancel(){this.cancelled=true;resolve();}};calls.push({node,frames,duration,animation});return animation;}};
 for(const row of rows){row.cloneNode=()=>{};row.getClientRects=()=>[{}];row.getBoundingClientRect=()=>({left:0,top:0});for(const node of row.children.slice(0,2)){node.getBoundingClientRect=()=>({left:8,top:8,width:100,height:80});node.cloneNode=()=>f.host.ownerDocument.createElement(node.tag);node.removeEventListener=(name,fn)=>{if(node.listeners.get(name)===fn)node.listeners.delete(name);};}}
 f.view.render({cards,busy:true});assert.equal(calls.length,0,'busy entry keeps existing content still');const next=cards.map((card,index)=>({...card,id:'new-'+index,name:'Ny '+index}));f.view.render({cards:next});
 assert.deepEqual(f.nodes.get('result-list').children,rows);assert.equal(calls.length,8);assert.equal(rows.every(row=>row.children.slice(4).every(layer=>layer.style.cssText.includes('grid-area:auto!important'))),true,'absolute layers must not inherit source grid-area as their containing block');assert.equal(calls.some(call=>rows.includes(call.node)||rows.some(row=>row.children[3]===call.node)),false);assert.equal(calls.every(call=>call.duration===200&&call.frames.every(frame=>Object.keys(frame).length===1&&'opacity' in frame)),true);
 f.view.render({cards:next});assert.equal(calls.length,8,'same content never restarts');f.view.cleanup();await Promise.resolve();assert.equal(f.view.contentTransitions.size,0);assert.equal(calls.every(call=>call.animation.cancelled),true);assert.equal(rows.every(row=>row.children.length===4),true,'temporary content layers removed');
});

test('an artwork crossfade waits for current decode and a replacement cancels stale listeners and layers',async()=>{
 const f=retainedResultSurface();f.view.render({cards:resultCards()});const row=f.nodes.get('result-list').children[0],calls=[];f.host.motion={reduced:false,animate(node){let resolve;const a={finished:new Promise(done=>resolve=done),cancel(){resolve();}};calls.push(node);return a;}};row.cloneNode=()=>{};row.getClientRects=()=>[{}];row.getBoundingClientRect=()=>({left:0,top:0});for(const node of row.children.slice(0,2)){node.getBoundingClientRect=()=>({left:8,top:8,width:100,height:80});node.cloneNode=()=>f.host.ownerDocument.createElement(node.tag);node.removeEventListener=(name,fn)=>{if(node.listeners.get(name)===fn)node.listeners.delete(name);};}
 const art=row.children[0],show=f.view.captureContent(row);art.dataset.artworkPending='true';show();assert.equal(calls.length,2,'only copy starts before decode');const oldLoad=art.listeners.get('load');oldLoad();assert.equal(calls.length,2,'late old load cannot start an image awaiting current decode');const replacement=f.view.captureContent(row);oldLoad();assert.equal(calls.length,2,'cancelled closure cannot animate new content');delete art.dataset.artworkPending;replacement();assert.equal(calls.length,6);f.view.cleanup();await Promise.resolve();assert.equal(row.children.length,4);assert.equal(art.listeners.has('load'),false);f.host.motion.reduced=true;f.view.captureContent(row)();assert.equal(calls.length,6,'reduced motion has no new transient layers');
});

test('refresh slot reuse cannot carry previous account or room content into a new scope',()=>{
 const f=retainedResultSurface(),cards=resultCards();f.host.liveCatalogue={account:'one'};f.host.liveSnapshot={bootId:'boot',roomId:'kitchen'};f.view.render({cards});const old=[...f.nodes.get('result-list').children];f.view.render({cards,busy:true});f.host.liveCatalogue.account='two';f.view.render({cards:cards.map(card=>({...card,id:'different-'+card.id}))});assert.equal(f.nodes.get('result-list').children.some(row=>old.includes(row)),false);assert.equal(f.view.contentTransitions.size,0);f.view.cleanup();
});

test('account source provenance uses the existing reserved footer without displacing cards or hiding errors',()=>{
 const f=retainedResultSurface(),cards=sourceMusicCards([{uri:'spotify:playlist:0123456789ABCDEFGHIJKL',name:'Authored playlist',artist:'Playliste'}],'account_playlists'),summary='Dine playlister · Første side · 4 ejede eller fulgte playlister';
 f.view.render({cards,collection:'top',sourceSummary:summary});const row=[...f.view.rows.values()][0],footer=f.view.empty;assert.equal(footer.hidden,false);assert.equal(footer.textContent,summary);
 f.view.render({cards,collection:'top',sourceSummary:summary,busy:true});assert.equal(footer.hidden,true);assert.equal([...f.view.rows.values()][0],row);
 f.view.render({cards,collection:'top',sourceSummary:summary,status:'Kunne ikke opdatere · viser seneste udvalg.'});assert.equal(footer.hidden,false);assert.match(footer.textContent,/Kunne ikke hente/);assert.equal(footer.dataset.refreshOutcome,'error');assert.equal([...f.view.rows.values()][0],row);
 f.view.render({cards,collection:'top'});assert.equal(footer.hidden,true);f.view.cleanup();
});

test('confirmed consumed catalogue disables its last dispatched retained row while another explicit choice stays usable',()=>{
 const f=retainedResultSurface();f.host.musicResults=f.view;const catalogue=new LiveMusicCatalogueView(f.host,()=>{});f.host.liveCatalogue=catalogue;catalogue.account='account';catalogue.connected=true;catalogue.selected='top';catalogue.capabilities=['top','targets'];const cards=resultCards(),entry={cards,actionDispatched:true,selectionConfirmed:true,selectionSpent:true,dispatchedCardId:cards[0].id};catalogue.entries.set(catalogue.key(),entry);catalogue.cards=cards;catalogue.canRenewEntry=()=>true;catalogue.render();const first=f.view.rows.get(cards[0].id),second=f.view.rows.get(cards[1].id);assert.equal(first.disabled,true);assert.equal(second.disabled,false);assert.equal(catalogue.cards,cards);assert.equal(catalogue.cards[0],cards[0]);entry.dispatchedCardId=cards[1].id;catalogue.render();assert.equal(f.view.rows.get(cards[0].id),first);assert.equal(first.disabled,false);assert.equal(second.disabled,true);
});
